using System;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class MedicalStaffTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Medical: "+name);}}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-medical-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{Franchise f=Franchise.Create(new Profile(),new Roster());f.Credits=100;ClubPlayer p=f.Starter(f.UserTeam,0);p.InjuryWeeks=3;p.InjuryType="BIG HIT";int baseCosts=f.OperatingCosts(f.UserTeam,false);Check(f.HireMedical(1)&&f.Credits==92&&f.Club.MedicalStaff==1&&p.InjuryWeeks==3,"tier 1 costs 8 and never heals instantly");Check(f.OperatingCosts(f.UserTeam,false)==baseCosts+1,"medical running costs included in forecasts");Check(!f.HireMedical(1)&&f.Credits==92,"same staff cannot be billed twice");Check(f.HireMedical(3)&&f.Credits==60&&f.OperatingCosts(f.UserTeam,false)==baseCosts+2,"elite staff costs 32 plus two per game");f=Franchise.Load(new Profile(),new Roster());Check(f.Club.MedicalStaff==3&&f.Credits==60,"medical staff and costs survive save/load");p=f.Starter(f.UserTeam,0);typeof(Franchise).GetMethod("RecoverInjuries",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,null);Check(p.InjuryWeeks==1,"elite care advances recovery two weeks");typeof(Franchise).GetMethod("RecoverInjuries",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,null);Check(p.InjuryWeeks==0&&p.InjuryType=="","fully healed injury clears without negative duration");Check(f.HireMedical(0)&&f.Credits==60&&f.OperatingCosts(f.UserTeam,false)==baseCosts,"downgrade removes future expense with no refund");f.Credits=7;Check(!f.HireMedical(1)&&f.Club.MedicalStaff==0&&f.Credits==7,"unaffordable hire leaves medical team and cash unchanged");f.Credits=100;f.HireMedical(2);int extra=0;for(int n=0;n<100;n++){f.Round=n;p.InjuryWeeks=3;typeof(Franchise).GetMethod("RecoverInjuries",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,null);if(p.InjuryWeeks==1)extra++;}Check(extra==50,"sports medical gives exactly 50 percent extra progress across 100 weeks");f.Round=0;f.Fired=true;Check(!f.HireMedical(3),"dismissed coach cannot spend club money");Console.WriteLine("Medical staff: "+checks+" checks, "+failures+" failures");return failures;}finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
}
